package com.monstermonitor;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import java.awt.Color;

/**
 * The MonsterMonitorConfig interface defines the configuration options for Monster Monitor.
 * It allows users to customize settings such as progress bar colors, overlay visibility,
 * and kill limit notifications.
 */
@ConfigGroup("monster monitor")
public interface MonsterMonitorConfig extends Config {

    @ConfigSection(
            name = "Display & Menus",
            description = "Configure the overlay and NPC right-click options.",
            position = 0
    )
    String displaySection = "displaySection";

    /**
     * Configures whether the Monster Monitor overlay should be displayed.
     *
     * @return true if the overlay should be shown, false otherwise
     */
    @ConfigItem(
            keyName = "showOverlay",
            name = "Show Overlay",
            description = "Toggle to display or hide the Monster Monitor overlay",
            position = 0,
            section = displaySection
    )
    default boolean showOverlay() {
        return true; // Default to showing the overlay
    }

    @ConfigItem(
            keyName = "showTitle",
            name = "Show Overlay Title",
            description = "Toggle the display of the overlay title",
            position = 1,
            section = displaySection
    )
    default boolean showTitle() {
        return true;
    }

    /**
     * Configures whether right-click menu entries should be displayed.
     *
     * @return true if the right-click menu entries should be shown, false otherwise
     */
    @ConfigItem(
            keyName = "showRightClickMenuEntries",
            name = "Show Right-Click Menu Entries",
            description = "Toggle to show or hide the right-click menu entries for NPCs.",
            position = 2,
            section = displaySection
    )
    default boolean showRightClickMenuEntries() {
        return true; // Default to showing right-click menu entries
    }

    @ConfigSection(
            name = "Progress Bar Colors",
            description = "Configure the progress bar gradient.",
            position = 1
    )
    String progressBarColorsSection = "progressBarColorsSection";

    /**
     * Configures the colors for the progress bar.
     *
     * @return the start color of the progress bar.
     */
    @ConfigItem(
            keyName = "progressBarStartColor",
            name = "Start Color",
            description = "Select the color for the start of the progress bar.",
            position = 0,
            section = progressBarColorsSection
    )
    default Color progressBarStartColor() {
        return new Color(139, 0, 0); // Dark red
    }

    /**
     * Configures the midpoint color for the progress bar.
     *
     * @return the midpoint color of the progress bar.
     */
    @ConfigItem(
            keyName = "progressBarMidColor",
            name = "Midpoint Color",
            description = "Select the color for the midpoint of the progress bar.",
            position = 1,
            section = progressBarColorsSection
    )
    default Color progressBarMidColor() {
        return new Color(204, 102, 0); // Dark orange
    }

    /**
     * Configures the end color for the progress bar.
     *
     * @return the end color of the progress bar.
     */
    @ConfigItem(
            keyName = "progressBarEndColor",
            name = "End Color",
            description = "Select the color for the end of the progress bar.",
            position = 2,
            section = progressBarColorsSection
    )
    default Color progressBarEndColor() {
        return new Color(0, 128, 0); // Dark green
    }

    /**
     * Resets progress bar colors to their default values when toggled.
     */
    @ConfigItem(
            keyName = "resetProgressBarColors",
            name = "Reset Colors",
            description = "Toggle to reset all progress bar colors to their default values.",
            position = 3,
            section = progressBarColorsSection
    )
    default boolean resetProgressBarColors() {
        return false;
    }

    @ConfigSection(
            name = "Notifications",
            description = "Configure notifications when an NPC kill limit is reached.",
            position = 2
    )
    String notificationsSection = "notificationsSection";

    /**
     * Configures whether a notification should be sent when a kill limit is reached.
     *
     * @return true if notifications should be sent when the kill limit is reached, false otherwise
     */
    @ConfigItem(
            keyName = "notifyOnLimit",
            name = "Enable Notifications",
            description = "Notify when a kill limit is reached. Also requires Notify to be enabled for that NPC.",
            position = 0,
            section = notificationsSection
    )
    default boolean notifyOnLimit() {
        return true;
    }

    /**
     * Configures whether chat notifications should be shown when kill limits are reached.
     *
     * @return true if chat notifications should be shown, false otherwise
     */
    @ConfigItem(
            keyName = "showChatNotifications",
            name = "Chat Messages",
            description = "Show notifications about reaching kill limits in the chat window.",
            position = 1,
            section = notificationsSection
    )
    default boolean showChatNotifications() {
        return true; // Default to showing chat notifications
    }

    /**
     * Configures whether the popup notification should be displayed when a kill limit is reached.
     *
     * @return true if the popup should be shown, false otherwise
     */
    @ConfigItem(
            keyName = "showPopup",
            name = "Show Popup",
            description = "Display a popup when the kill limit is reached",
            position = 2,
            section = notificationsSection
    )
    default boolean showPopup() {
        return true;
    }

    /**
     * Configures whether sound alerts should be enabled for notifications.
     *
     * @return true if sound alerts should be enabled, false otherwise
     */
    @ConfigItem(
            keyName = "enableSoundAlerts",
            name = "Sound Alerts",
            description = "Enable sound alerts for notifications.",
            position = 3,
            section = notificationsSection
    )
    default boolean enableSoundAlerts() {
        return true; // Default to enabling sound alerts
    }

    /**
     * Configures the custom notification message displayed when a kill limit is reached.
     *
     * @return the custom notification message
     */
    @ConfigItem(
            keyName = "customNotificationMessage",
            name = "Custom Message",
            description = "Message shown in chat when a kill limit is reached. Use {npc} for the NPC name.",
            position = 4,
            section = notificationsSection
    )
    default String customNotificationMessage() {
        return "Kill limit reached for {npc}"; // Default message
    }

}

package com.monstermonitor;

import com.monstermonitor.data.MonsterMonitorLogger;
import com.monstermonitor.data.NpcData;
import com.monstermonitor.menus.MonsterMonitorMenuHandler;
import com.monstermonitor.tracking.DeathTracker;
import com.monstermonitor.ui.MonsterMonitorOverlay;
import com.monstermonitor.ui.MonsterMonitorPanel;
import com.monstermonitor.ui.MonsterMonitorPopup;

import com.google.inject.Provides;
import lombok.Getter;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.eventbus.EventBus;

import javax.inject.Inject;
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import java.util.function.Supplier;

@PluginDescriptor(
        name = "Monster Monitor",
        internalName = "monster-monitor",
        legacyDataDirectory = "monstermonitor",
        description = "Tracks NPC kills and allows setting kill limits",
        tags = {"npc", "kill", "limit", "mm"}
)
public class MonsterMonitorPlugin extends Plugin
{
    @Inject
    MonsterMonitorConfig config;

    @Inject
    private EventBus eventBus;

    @Inject
    MonsterMonitorLogger logger;

    @Inject
    MonsterMonitorOverlay overlay;

    @Inject
    MonsterMonitorPanel panel;

    @Inject
    OverlayManager overlayManager;

    @Inject
    ClientToolbar clientToolbar;

    @Inject
    Client client;

    @Inject
    ClientThread clientThread;

    @Inject
    DeathTracker deathTracker;

    @Inject
    MonsterMonitorMenuHandler menuHandler;

    @Inject
    private MonsterMonitorPopup popup;

    @Inject
    private ConfigManager configManager;

    private NavigationButton navButton;
    private volatile boolean initialized;
    private volatile boolean running;
    private String playerName;
    @Getter
    private volatile int sessionId;
    private boolean overlayVisible;
    private final AtomicBoolean uiUpdatePending = new AtomicBoolean();

    @Provides
    MonsterMonitorConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(MonsterMonitorConfig.class);
    }

    public void resetProgressBarColors() {
        configManager.unsetConfiguration("monster monitor", "progressBarStartColor");
        configManager.unsetConfiguration("monster monitor", "progressBarMidColor");
        configManager.unsetConfiguration("monster monitor", "progressBarEndColor");
        configManager.unsetConfiguration("monster monitor", "resetProgressBarColors");
        updateUI();
    }

    /**
     * Initializes the plugin, setting up UI components and registering events.
     */
    @Override
    protected void startUp() throws Exception
    {
        running = true;
        eventBus.register(deathTracker);
        eventBus.register(menuHandler);
        eventBus.register(popup);

        // Load the plugin icon and create a navigation button.
        final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/net/runelite/client/plugins/MonsterMonitor/icon.png");
        navButton = NavigationButton.builder()
                .tooltip("Monster Monitor")
                .icon(icon)
                .panel(panel)
                .build();
        clientToolbar.addNavigation(navButton);
        clientThread.invoke(() -> {
            if (running) {
                deathTracker.reset();
                popup.startUpPopup();
                initializePlayer();
            }
        });
    }

    /**
     * Handles plugin shutdown, including saving logs and removing UI elements.
     */
    @Override
    protected void shutDown() throws Exception
    {
        running = false;
        initialized = false;
        sessionId++;
        playerName = null;
        eventBus.unregister(deathTracker);
        eventBus.unregister(menuHandler);
        eventBus.unregister(popup);
        overlayManager.remove(overlay);
        overlayVisible = false;
        overlay.updateOverlayData(Collections.emptyList());
        clientToolbar.removeNavigation(navButton);
        clientThread.invoke(() -> {
            deathTracker.reset();
            popup.shutdownPopup();
        });
        logger.close();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGIN_SCREEN) {
            initialized = false;
            sessionId++;
            playerName = null;
            deathTracker.reset();
            popup.shutdownPopup();
            logger.close();
            SwingUtilities.invokeLater(panel::resetSession);
            updateUI();
        } else if (event.getGameState() == GameState.HOPPING) {
            deathTracker.reset();
            popup.shutdownPopup();
        } else if (event.getGameState() == GameState.LOGGED_IN) {
            popup.startUpPopup();
            initializePlayer();
        }
    }

    @Subscribe(priority = 1)
    public void onGameTick(GameTick event)
    {
        initializePlayer();
    }

    private void initializePlayer() {
        Player localPlayer = client.getLocalPlayer();
        if (!running || localPlayer == null || localPlayer.getName() == null) {
            return;
        }
        String name = localPlayer.getName();
        if (initialized && name.equals(playerName)) {
            return;
        }

        initialized = false;
        sessionId++;
        deathTracker.reset();
        popup.shutdownPopup();
        int expectedSession = sessionId;
        logger.initialize(this::getPluginDirectory, name).thenRun(() -> {
            if (running && expectedSession == sessionId) {
                updateUI();
            }
        });
        playerName = name;
        initialized = true;
        popup.startUpPopup();
        SwingUtilities.invokeLater(panel::resetSession);
        updateUI();
    }

    /**
     * Logs a death for a specific NPC and updates the UI accordingly.
     */
    public void logDeath(String npcName)
    {
        if (running && initialized)
        {
            int expectedSession = sessionId;
            logger.logDeath(npcName).thenAccept(npcData -> clientThread.invoke(() -> {
                if (npcData != null && running && initialized && expectedSession == sessionId) {
                    updateUI();
                    checkKillLimit(npcData);
                }
            }));
        }
    }

    /**
     * Updates the UI elements, including the overlay and panel.
     */
    public void updateUI()
    {
        if (running && uiUpdatePending.compareAndSet(false, true))
        {
            SwingUtilities.invokeLater(() -> {
                uiUpdatePending.set(false);
                if (running) {
                    updateOverlay();
                    panel.updatePanel();
                }
            });
        }
    }

    /**
     * Checks whether this kill reached a limit and sends one notification.
     */
    private void checkKillLimit(NpcData npcData)
    {
        if (!npcData.isLimitSet() || npcData.getKillLimit() <= 0
                || npcData.getKillCountForLimit() != npcData.getKillLimit()
                || !npcData.isNotifyOnLimit() || !config.notifyOnLimit())
        {
            return;
        }

        if (config.enableSoundAlerts()) {
            Toolkit.getDefaultToolkit().beep();
        }
        if (config.showChatNotifications()) {
            String message = "<col=ff0000>" + config.customNotificationMessage().replace("{npc}", npcData.getNpcName()) + "</col>";
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
        }
        if (config.showPopup()) {
            popup.showPopup(npcData.getNpcName());
        }
    }

    /**
     * Retrieves the list of tracked NPCs.
     */
    public List<NpcData> getTrackedNpcs()
    {
        return logger.getNpcs();
    }

    public void updateOverlay() {
        boolean hasGoals = overlay.updateOverlayData(getTrackedNpcs());
        boolean visible = running && initialized && config.showOverlay() && hasGoals;
        if (visible != overlayVisible) {
            if (visible) {
                overlayManager.add(overlay);
            } else {
                overlayManager.remove(overlay);
            }
            overlayVisible = visible;
        }
    }

    public void updateNpcData(String npcName, Consumer<NpcData> update) {
        mutateLog(() -> logger.updateNpcData(npcName, update));
    }

    public void removeNpcFromLog(String npcName) {
        mutateLog(() -> logger.removeNpcFromLog(npcName));
    }

    private void mutateLog(Supplier<CompletableFuture<Void>> change) {
        int expectedSession = sessionId;
        clientThread.invoke(() -> {
            if (running && initialized && expectedSession == sessionId) {
                change.get().thenRun(() -> {
                    if (running && expectedSession == sessionId) {
                        updateUI();
                    }
                });
            }
        });
    }

    /**
     * Sets the specified NPC to be monitored with a given kill limit.
     */
    public void setNpcToMonitor(String npcName, int killLimit) {
        if (killLimit < 0) {
            return;
        }
        updateNpcData(npcName, npcData -> {
            if (!npcData.isLimitSet() || npcData.getKillLimit() != killLimit) {
                npcData.resetKillCountForLimit();
            }
            npcData.setKillLimit(killLimit);
            npcData.setLimitSet(true);
            npcData.setIgnored(false);
        });
    }

    /**
     * Sets the specified NPC to be ignored, preventing it from being tracked.
     */
    public void setNpcToIgnore(String npcName) {
        updateNpcData(npcName, npcData -> {
            npcData.setIgnored(true);
            npcData.setLimitSet(false);
            npcData.setKillLimit(0);
            npcData.resetKillCountForLimit();
        });
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!"monster monitor".equals(event.getGroup())) {
            return;
        }
        if ("resetProgressBarColors".equals(event.getKey()) && Boolean.parseBoolean(event.getNewValue())) {
            resetProgressBarColors();
        } else {
            updateUI();
        }
    }
}

package com.monstermonitor.data;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.BufferedReader;
import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Callable;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import java.util.stream.Stream;

/**
 * The MonsterMonitorLogger class is responsible for logging and managing data related to NPC kills.
 * It handles reading from and writing to log files specific to each player,
 * maintains the current state of the tracked NPCs, and handles NPC ignore/monitor states.
 */
@Singleton
@Slf4j
public class MonsterMonitorLogger {
	private static final TypeToken<Map<String, NpcData>> LOG_TYPE = new TypeToken<Map<String, NpcData>>() {};
	@Inject
	private Gson gson;
	@Inject
	private ScheduledExecutorService executor;
	private CompletableFuture<Void> pendingWork = CompletableFuture.completedFuture(null);
	private Session session;
	private ScheduledFuture<?> pendingSave;

	/**
	 * Initializes the logger, creating directories and loading logs.
	 */
	public synchronized CompletableFuture<Void> initialize(Callable<Filepath> root, String playerName) {
		close();
		Session next = new Session();
		session = next;
		return submit(() -> {
			try {
				Filepath directory = playerDirectory(root.call(), playerName);
				next.logFilePath = directory.joinSegment("monster_monitor_log.json");
				directory.createDirectories();
				loadLog(next);
				next.writable = true;
			} catch (Exception e) {
				log.warn("Failed to initialize Monster Monitor logs for {}", playerName, e);
			}
			return null;
		});
	}

	private synchronized <T> CompletableFuture<T> submit(Supplier<T> task) {
		CompletableFuture<T> result = pendingWork.thenApplyAsync(ignored -> task.get(), executor);
		pendingWork = result.handle((value, error) -> {
			if (error != null) {
				log.warn("Failed to update Monster Monitor logs", error);
			}
			return null;
		});
		return result;
	}

	private Filepath playerDirectory(Filepath root, String name) throws IOException {
		try {
			return root.joinSegment(name);
		} catch (IllegalArgumentException e) {
			Filepath directory = root.joinSegment("player-" + URLEncoder.encode(name, StandardCharsets.UTF_8));
			if (!directory.exists() && root.exists()) {
				try (Stream<Filepath> paths = root.walk(1)) {
					Filepath legacy = paths.filter(path -> !path.isRoot() && path.isDirectory() && path.getFileName().equals(name))
							.findFirst().orElse(null);
					if (legacy != null) {
						legacy.moveTo(directory);
					}
				}
			}
			return directory;
		}
	}

	/**
	 * Loads the NPC log from the file and initializes missing fields for compatibility.
	 */
	private void loadLog(Session current) throws IOException {
		Filepath logFilePath = current.logFilePath;
		if (!logFilePath.exists()) {
			return;
		}

		Map<String, NpcData> loadedLog;
		try (BufferedReader reader = logFilePath.openBufferedReader()) {
			loadedLog = gson.fromJson(reader, LOG_TYPE.getType());
		} catch (JsonParseException e) {
			Filepath backup = logFilePath.getParent().joinSegment("monster_monitor_log." + System.currentTimeMillis() + ".bak");
			logFilePath.copyTo(backup);
			log.warn("Invalid Monster Monitor log backed up to {}", backup, e);
			return;
		}

		if (loadedLog == null) {
			return;
		}
		synchronized (current.npcLog) {
			loadedLog.forEach((npcName, npcData) -> {
				if (npcName != null && npcData != null) {
					npcData.setNpcName(npcName);
					npcData.setTotalKillCount(Math.max(0, npcData.getTotalKillCount()));
					npcData.setKillCountForLimit(Math.max(0, npcData.getKillCountForLimit()));
					npcData.setKillLimit(Math.max(0, npcData.getKillLimit()));
					current.npcLog.put(npcName, npcData);
				}
			});
		}
	}

	/**
	 * Logs the death of an NPC, updating its kill count and queuing a save operation.
	 *
	 * @param npcName the name of the NPC
	 * @return a future containing the updated data, or null if inactive or ignored
	 */
	public synchronized CompletableFuture<NpcData> logDeath(String npcName) {
		Session current = session;
		if (current == null) {
			return CompletableFuture.completedFuture(null);
		}
		return submit(() -> {
			NpcData snapshot;
			synchronized (current.npcLog) {
				NpcData npcData = current.npcLog.computeIfAbsent(npcName, NpcData::new);
				if (npcData.isIgnored()) {
					return null;
				}
				npcData.incrementKillCount();
				current.npcLog.remove(npcName);
				current.npcLog.put(npcName, npcData);
				snapshot = new NpcData(npcData);
			}
			saveLogAsync(current);
			return snapshot;
		});
	}

	/**
	 * Coalesces bursts of changes into a single background save.
	 */
	private synchronized void saveLogAsync(Session current) {
		if (session != current || !current.writable || pendingSave != null) {
			return;
		}
		pendingSave = executor.schedule(() -> {
			synchronized (this) {
				if (session == current) {
					pendingSave = null;
					saveLog();
				}
			}
		}, 250, TimeUnit.MILLISECONDS);
	}

	/**
	 * Saves the NPC log to disk without holding the data lock during file I/O.
	 */
	public synchronized CompletableFuture<Void> saveLog() {
		Session current = session;
		return current == null ? pendingWork : submit(() -> {
			writeLog(current);
			return null;
		});
	}

	private void writeLog(Session current) {
		if (!current.writable) {
			return;
		}
		Filepath destination = current.logFilePath;
		String json;
		synchronized (current.npcLog) {
			json = gson.toJson(current.npcLog, LOG_TYPE.getType());
		}

		Filepath temporary = null;
		try {
			temporary = destination.getParent().createTempFile("monster-monitor-", ".tmp");
			temporary.write(json);
			try {
				temporary.moveTo(destination, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
			} catch (AtomicMoveNotSupportedException e) {
				temporary.moveTo(destination, StandardCopyOption.REPLACE_EXISTING);
			}
		} catch (IOException e) {
			log.warn("Failed to save Monster Monitor log to {}", destination, e);
		} finally {
			if (temporary != null) {
				try {
					temporary.deleteIfExists();
				} catch (IOException e) {
					log.warn("Failed to remove temporary Monster Monitor log {}", temporary, e);
				}
			}
		}
	}

	/**
	 * Retrieves a snapshot of the current NPC log.
	 */
	public synchronized List<NpcData> getNpcs() {
		if (session == null) {
			return List.of();
		}
		synchronized (session.npcLog) {
			return session.npcLog.values().stream().map(NpcData::new).collect(Collectors.toList());
		}
	}

	public synchronized NpcData getNpcData(String npcName) {
		if (session == null) {
			return null;
		}
		synchronized (session.npcLog) {
			NpcData data = session.npcLog.get(npcName);
			return data == null ? null : new NpcData(data);
		}
	}

	/**
	 * Removes an NPC from the log by name.
	 */
	public CompletableFuture<Void> removeNpcFromLog(String npcName) {
		return updateLog(data -> data.remove(npcName));
	}

	/**
	 * Updates current data under the same lock as kill logging, retaining any intervening kills.
	 */
	public CompletableFuture<Void> updateNpcData(String npcName, Consumer<NpcData> update) {
		return updateLog(data -> update.accept(data.computeIfAbsent(npcName, NpcData::new)));
	}

	private synchronized CompletableFuture<Void> updateLog(Consumer<Map<String, NpcData>> update) {
		Session current = session;
		if (current == null) {
			return CompletableFuture.completedFuture(null);
		}
		return submit(() -> {
			synchronized (current.npcLog) {
				update.accept(current.npcLog);
			}
			saveLogAsync(current);
			return null;
		});
	}

	/**
	 * Clears the active session and queues its final save without blocking shutdown.
	 */
	public synchronized CompletableFuture<Void> close() {
		cancelPendingSave();
		CompletableFuture<Void> saved = saveLog();
		session = null;
		return saved;
	}

	private void cancelPendingSave() {
		if (pendingSave != null) {
			pendingSave.cancel(false);
			pendingSave = null;
		}
	}

	private static class Session {
		private final Map<String, NpcData> npcLog = new LinkedHashMap<>();
		private Filepath logFilePath;
		private boolean writable;
	}
}

package com.monstermonitor.data;

import lombok.Getter;
import lombok.Setter;
import lombok.NoArgsConstructor;
import lombok.AllArgsConstructor;

/**
 * Represents the data associated with an NPC being tracked by Monster Monitor.
 * This class holds information such as the NPC's name, kill counts, kill limits,
 * whether the NPC is ignored (not logged), and whether notifications should be sent when a kill limit is reached.
 */
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
public class NpcData
{
    private String npcName; // Name of the NPC
    private int totalKillCount; // Total kills of this NPC
    private int killCountForLimit; // Progress towards the kill limit
    private int killLimit; // The set kill limit for this NPC
    private boolean limitSet; // Flag to track if the limit is set
    private boolean notifyOnLimit; // Flag to determine if notifications should be sent when the kill limit is reached
    private boolean ignored; // Flag to indicate if the NPC is ignored (true = ignored, false = tracked)

    /**
     * Constructor to create an NpcData object with just the NPC name.
     * Initializes other fields to default values.
     *
     * @param npcName the name of the NPC
     */
    public NpcData(String npcName)
    {
        this.npcName = npcName;
    }

    public NpcData(NpcData other)
    {
        this(other.npcName, other.totalKillCount, other.killCountForLimit, other.killLimit,
                other.limitSet, other.notifyOnLimit, other.ignored);
    }

    /**
     * Increment the total kill count and the kill count towards the limit.
     * This method is typically called when the player kills the tracked NPC.
     * Ignores incrementing counts if the NPC is marked as ignored.
     */
    public void incrementKillCount()
    {
        if (!ignored) {
            this.totalKillCount++;
            this.killCountForLimit++;
        }
    }

    /**
     * Reset only the progress towards the limit.
     * This method resets the kill count related to the limit while retaining the total kills.
     * Useful when the player wants to set a new limit but retain overall kill history.
     */
    public void resetKillCountForLimit()
    {
        this.killCountForLimit = 0;
    }

}

package com.monstermonitor.menus;

import com.monstermonitor.MonsterMonitorConfig;
import com.monstermonitor.MonsterMonitorPlugin;
import com.monstermonitor.data.MonsterMonitorLogger;
import com.monstermonitor.data.NpcData;

import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.events.MenuOpened;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Handles adding custom menu entries for Monster Monitor.
 * Manages the creation of "Monitor" and "Ignore" options.
 */
@Singleton
public class MonsterMonitorMenuHandler {
    private static final String MONITOR_OPTION = "Monitor";
    private static final String IGNORE_OPTION = "Ignore";
    @Inject
    private MonsterMonitorPlugin plugin;
    @Inject
    private MonsterMonitorLogger logger;
    @Inject
    private Client client;
    @Inject
    private MonsterMonitorConfig config;

    @Subscribe
    public void onMenuOpened(MenuOpened event) {
        if (!config.showRightClickMenuEntries()) {
            return;
        }

        for (MenuEntry menuEntry : event.getMenuEntries()) {
            NPC npc = menuEntry.getNpc();
            if (npc != null && npc.getCombatLevel() > 0 && "Attack".equals(Text.removeTags(menuEntry.getOption()))) {
                addCustomMenuOptions(npc);
                return;
            }
        }
    }

    private void addCustomMenuOptions(NPC npc) {
        if (npc.getName() == null) {
            return;
        }
        String npcName = Text.removeTags(npc.getName()).trim();
        String target = npcName + " (level-" + npc.getCombatLevel() + ")";
        NpcData npcData = logger.getNpcData(npcName);

        if (npcData == null || npcData.isIgnored() || !npcData.isLimitSet()) {
            addMenuOption(MONITOR_OPTION, target, () -> plugin.setNpcToMonitor(npcName, 10));
        }
        if (npcData == null || !npcData.isIgnored()) {
            addMenuOption(IGNORE_OPTION, target, () -> plugin.setNpcToIgnore(npcName));
        }
    }

    private void addMenuOption(String option, String target, Runnable action) {
        int session = plugin.getSessionId();
        client.getMenu()
                .createMenuEntry(1)
                .setOption(option)
                .setTarget(target)
                .setType(MenuAction.RUNELITE)
                .onClick(e -> {
                    if (session == plugin.getSessionId()) {
                        action.run();
                    }
                });
    }
}

package com.monstermonitor.tracking;

import com.monstermonitor.MonsterMonitorPlugin;

import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.WorldView;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.gameval.NpcID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

/**
 * Tracks and manages NPC deaths and interactions for Monster Monitor.
 * This class handles tracking of kills, including special NPCs that do not fire the ActorDeath event.
 */
@Singleton
public class DeathTracker {
    @Inject
    private Client client;
    @Inject
    private MonsterMonitorPlugin plugin;
    @Inject
    private SpecialNpcTracker specialNpcTracker;

    private final Map<NPC, Interaction> interactions = new IdentityHashMap<>();
    private boolean temporossLogged;
    private static final int INTERACTION_TIMEOUT_TICKS = 7;

    private static final Map<String, Set<Integer>> FINAL_PHASE_IDS = Map.ofEntries(
            Map.entry("Kalphite Queen", Set.of(NpcID.KALPHITE_FLYINGQUEEN)),
            Map.entry("The Nightmare", Set.of(NpcID.NIGHTMARE_DEAD, NpcID.NIGHTMARE_DYING)),
            Map.entry("Phosani's Nightmare", Set.of(NpcID.NIGHTMARE_CHALLENGE_DEAD, NpcID.NIGHTMARE_CHALLENGE_DYING)),
            Map.entry("Alchemical Hydra", Set.of(NpcID.HYDRABOSS_FINALDEATH)),
            Map.entry("Hydra", Set.of(NpcID.HYDRA)),
            Map.entry("Phantom Muspah", Set.of(NpcID.MUSPAH_FINAL, NpcID.MUSPAH_FINAL_QUEST)),
            Map.entry("Dusk", Set.of(NpcID.GARGBOSS_DUSK_DEATH)),
            Map.entry("Abyssal Sire", Set.of(NpcID.ABYSSALSIRE_SIRE_PANICKING)),
            Map.entry("Kephri", Set.of(NpcID.TOA_KEPHRI_BOSS_DEAD)),
            Map.entry("Verzik Vitur", Set.of(NpcID.VERZIK_PHASE3, NpcID.VERZIK_PHASE3_STORY, NpcID.VERZIK_PHASE3_HARD)),
            Map.entry("Great Olm", Set.of(NpcID.OLM_HEAD))
    );

    private static final Set<Integer> EXCLUDED_NPC_IDS = Set.of(
            NpcID.HUEY_TAIL, NpcID.HUEY_TAIL_BROKEN, NpcID.HUEY_TAIL_PROJECTILE,
            NpcID.HUEY_BODY_PART, NpcID.HUEY_BODY_PART_BROKEN,
            NpcID.AMOXLIATL_ICE_BLOCK, NpcID.PMOON_BOSS_ICICLE_CRACKED,
            NpcID.OLM_HAND_RIGHT_SPAWNING, NpcID.OLM_HAND_LEFT_SPAWNING,
            NpcID.OLM_HAND_RIGHT, NpcID.OLM_HAND_LEFT,
            NpcID.OLM_HAND_RIGHT_DYING, NpcID.OLM_HAND_LEFT_DYING,
            NpcID.GARGBOSS_DAWN_DEATH
    );

    private static final Set<Integer> DEFEATED_NPC_IDS = Set.of(
            NpcID.NIGHTMARE_DEAD, NpcID.NIGHTMARE_CHALLENGE_DEAD,
            NpcID.HYDRABOSS_FINALDEATH, NpcID.GARGBOSS_DUSK_DEATH, NpcID.TOA_KEPHRI_BOSS_DEAD
    );

    @Subscribe
    public void onInteractingChanged(InteractingChanged event) {
        if (event.getSource() == client.getLocalPlayer() && event.getTarget() instanceof NPC) {
            trackNpc((NPC) event.getTarget(), false);
        }
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event) {
        if (event.getActor() instanceof NPC && event.getHitsplat().isMine()) {
            trackNpc((NPC) event.getActor(), true);
        }
    }

    private void trackNpc(NPC npc, boolean engaged) {
        Interaction interaction = interactions.computeIfAbsent(npc, ignored -> new Interaction());
        String name = npc.getName();
        if (name != null) {
            interaction.name = Text.removeTags(name).trim();
        }
        interaction.lastTick = client.getTickCount();
        interaction.engaged |= engaged;
    }

    @Subscribe
    public void onActorDeath(ActorDeath event) {
        Actor actor = event.getActor();
        if (actor instanceof NPC) {
            interactions.computeIfAbsent((NPC) actor, ignored -> new Interaction()).dead = true;
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if ((event.getType() == ChatMessageType.GAMEMESSAGE || event.getType() == ChatMessageType.SPAM)
                && "The skies clear as Tempoross retreats to the depths.".equalsIgnoreCase(Text.removeTags(event.getMessage()).trim())) {
            logTempoross();
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOADING) {
            temporossLogged = false;
        }
    }

    private void logTempoross() {
        if (!temporossLogged) {
            // Keep this guard after the NPC despawns so the completion message cannot count it twice.
            temporossLogged = true;
            plugin.logDeath("Tempoross");
        }
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event) {
        Interaction interaction = interactions.get(event.getNpc());
        if (interaction != null) {
            interaction.despawned = true;
        }
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        int currentTick = client.getTickCount();
        Iterator<Map.Entry<NPC, Interaction>> iterator = interactions.entrySet().iterator();
        while (iterator.hasNext()) {
            Map.Entry<NPC, Interaction> entry = iterator.next();
            NPC npc = entry.getKey();
            Interaction interaction = entry.getValue();
            boolean special = specialNpcTracker.isSpecialNpc(npc);
            boolean recent = currentTick - interaction.lastTick <= INTERACTION_TIMEOUT_TICKS;

            // Defer deaths until the packet's hitsplats and NPC transformations have arrived.
            boolean dead = interaction.dead || npc.getHealthRatio() == 0 || DEFEATED_NPC_IDS.contains(npc.getId());
            if (special) {
                dead = specialNpcTracker.shouldLogNpc(npc, interaction.dead);
            }
            Set<Integer> finalIds = interaction.name == null ? null : FINAL_PHASE_IDS.get(interaction.name);
            if (!interaction.logged && interaction.engaged && (recent || special)
                    && dead && !EXCLUDED_NPC_IDS.contains(npc.getId())
                    && (finalIds == null || finalIds.contains(npc.getId()))) {
                interaction.logged = true;
                if ("Tempoross".equalsIgnoreCase(interaction.name)) {
                    logTempoross();
                } else {
                    plugin.logDeath(interaction.name == null ? "Unnamed NPC" : interaction.name);
                }
            }

            if (special && interaction.logged && !dead && !npc.isDead() && npc.getHealthRatio() > 0) {
                interaction.logged = false;
                interaction.engaged = false;
            }
            interaction.dead = false;

            WorldView worldView = npc.getWorldView();
            boolean active = worldView != null && worldView.npcs().byIndex(npc.getIndex()) == npc;
            if (interaction.despawned || !active || (!special && !recent)) {
                iterator.remove();
            }
        }
    }

    public void reset() {
        interactions.clear();
        temporossLogged = false;
    }

    private static class Interaction {
        private String name;
        private int lastTick;
        private boolean engaged;
        private boolean dead;
        private boolean logged;
        private boolean despawned;
    }
}

package com.monstermonitor.tracking;

import net.runelite.api.NPC;
import net.runelite.api.gameval.NpcID;

import javax.inject.Singleton;
import java.util.Set;

/**
 * Identifies special NPCs and their death conditions.
 * Personal damage and duplicate prevention are handled by DeathTracker for all NPCs.
 */
@Singleton
public class SpecialNpcTracker {
    private static final Set<Integer> SPECIAL_NPC_IDS = Set.of(
            NpcID.HUEY_HEAD, NpcID.HUEY_HEAD_RESPAWN_PLACEHOLDER,
            NpcID.HUEY_HEAD_INVULNERABLE, NpcID.HUEY_HEAD_DEFEATED, NpcID.HUEY_HEAD_ENRAGED,
            NpcID.AMOXLIATL, NpcID.AMOXLIATL_QUEST,
            NpcID.DUKE_SUCELLUS_INACTIVE, NpcID.DUKE_SUCELLUS_ASLEEP,
            NpcID.DUKE_SUCELLUS_AWAKE, NpcID.DUKE_SUCELLUS_DEAD,
            NpcID.DUKE_SUCELLUS_INACTIVE_QUEST, NpcID.DUKE_SUCELLUS_ASLEEP_QUEST,
            NpcID.DUKE_SUCELLUS_AWAKE_QUEST, NpcID.DUKE_SUCELLUS_DEAD_QUEST,
            NpcID.PMOON_BOSS_BLOOD_MOON_VIS, NpcID.PMOON_BOSS_ECLIPSE_MOON_VIS,
            NpcID.PMOON_BOSS_BLUE_MOON_VIS, NpcID.PMOON_BOSS_BLOOD_MOON,
            NpcID.PMOON_BOSS_BLUE_MOON, NpcID.PMOON_BOSS_ECLIPSE_MOON
    );

    public boolean isSpecialNpc(NPC npc) {
        return SPECIAL_NPC_IDS.contains(npc.getId());
    }

    public boolean shouldLogNpc(NPC npc, boolean actorDeath) {
        switch (npc.getId()) {
            case NpcID.HUEY_HEAD_DEFEATED:
            case NpcID.DUKE_SUCELLUS_DEAD:
            case NpcID.DUKE_SUCELLUS_DEAD_QUEST:
                return true;
            case NpcID.HUEY_HEAD:
            case NpcID.HUEY_HEAD_RESPAWN_PLACEHOLDER:
            case NpcID.HUEY_HEAD_INVULNERABLE:
            case NpcID.HUEY_HEAD_ENRAGED:
            case NpcID.DUKE_SUCELLUS_INACTIVE:
            case NpcID.DUKE_SUCELLUS_ASLEEP:
            case NpcID.DUKE_SUCELLUS_INACTIVE_QUEST:
            case NpcID.DUKE_SUCELLUS_ASLEEP_QUEST:
                return false;
            default:
                return actorDeath || npc.getHealthRatio() == 0;
        }
    }
}

package com.monstermonitor.ui;

import com.monstermonitor.MonsterMonitorPlugin;
import com.monstermonitor.data.NpcData;

import lombok.Getter;
import javax.swing.*;
import java.awt.*;
import java.util.function.Consumer;

/**
 * Represents a UI component (box) in Monster Monitor that displays information
 * about a specific NPC. The box shows the NPC's name, kill count, and provides options to
 * set kill limits, enable notifications, and other related settings.
 * This component also supports expanding and collapsing additional options via a dropdown.
 */
public class MonsterMonitorBox extends JPanel
{
    private static final Font OPTION_FONT = new Font("SansSerif", Font.BOLD, 11);
    private final MonsterMonitorPlugin plugin;
    @Getter
    private final NpcData npcData;
    private final int sessionId;
    @Getter
    private boolean dropdownVisible;
    private final JPanel optionsPanel;
    private JButton toggleButton;
    private JCheckBox setLimitCheckbox;
    private JSpinner limitSpinner;
    private JCheckBox notifyCheckbox;
    private boolean updatingControls;

    /**
     * Constructs the MonsterMonitorBox component and initializes its UI elements.
     *
     * @param plugin The MonsterMonitorPlugin instance that this box is part of.
     * @param npcData The NpcData associated with the NPC displayed in this box.
     * @param initialDropdownState The initial state of the dropdown (expanded or collapsed).
     */
    public MonsterMonitorBox(MonsterMonitorPlugin plugin, NpcData npcData, boolean initialDropdownState)
    {
        this.plugin = plugin;
        this.npcData = npcData;
        this.sessionId = plugin.getSessionId();
        this.dropdownVisible = initialDropdownState;

        setLayout(new BorderLayout());
        setBackground(new Color(60, 60, 60));
        setBorder(BorderFactory.createLineBorder(Color.GRAY));

        add(createNpcNameLabel(), BorderLayout.WEST);
        add(createToggleButton(), BorderLayout.EAST);

        // Create the options panel
        optionsPanel = createOptionsPanel();
        if (dropdownVisible) {
            add(optionsPanel, BorderLayout.SOUTH);
        }

        // Set the initial state of the checkbox and other UI elements
        updateOptionStateBasedOnIgnored();
    }

    /**
     * Creates the NPC name label displaying the NPC's name and kill count.
     *
     * @return The JLabel for the NPC's name.
     */
    private JLabel createNpcNameLabel()
    {
        JLabel npcNameLabel = new JLabel(npcData.getNpcName() + " x " + npcData.getTotalKillCount());
        npcNameLabel.setForeground(new Color(200, 200, 200));
        npcNameLabel.setFont(new Font("Arial", Font.BOLD, 12));
        npcNameLabel.setHorizontalAlignment(SwingConstants.LEFT);
        npcNameLabel.setBorder(BorderFactory.createEmptyBorder(2, 5, 2, 5));
        return npcNameLabel;
    }

    /**
     * Creates the toggle button for expanding or collapsing the options panel.
     *
     * @return The JButton used to toggle the dropdown visibility.
     */
    private JButton createToggleButton()
    {
        toggleButton = new JButton(dropdownVisible ? "▲" : "▼");
        toggleButton.setPreferredSize(new Dimension(16, 16));
        toggleButton.setBorder(BorderFactory.createEmptyBorder());
        toggleButton.setContentAreaFilled(false);
        toggleButton.setFocusPainted(false);
        toggleButton.setForeground(new Color(200, 150, 0));

        toggleButton.addActionListener(e -> setDropdownVisible(!dropdownVisible));
        return toggleButton;
    }

    /**
     * Creates the options panel that allows users to set a kill limit, enable notifications,
     * and interact with other related settings for the NPC.
     *
     * @return A JPanel containing the options controls.
     */
    private JPanel createOptionsPanel()
    {
        JPanel panel = new JPanel(new GridBagLayout());
        panel.setBackground(new Color(60, 60, 60));
        GridBagConstraints gbc = new GridBagConstraints();
        gbc.fill = GridBagConstraints.HORIZONTAL;
        gbc.insets = new Insets(2, 2, 2, 2);

        setLimitCheckbox = createSetLimitCheckbox();
        limitSpinner = createLimitSpinner();
        notifyCheckbox = createNotifyCheckbox();

        gbc.gridx = 0;
        gbc.weightx = 0.1;
        panel.add(setLimitCheckbox, gbc);

        gbc.gridx = 1;
        gbc.weightx = 0.3;
        panel.add(limitSpinner, gbc);

        gbc.gridx = 2;
        gbc.weightx = 0.1;
        panel.add(notifyCheckbox, gbc);

        return panel;
    }

    /**
     * Creates the checkbox to set a kill limit.
     *
     * @return A JCheckBox to enable or disable kill limit.
     */
    private JCheckBox createSetLimitCheckbox()
    {
        JCheckBox checkBox = createCheckbox("Set Limit", npcData.isLimitSet());
        checkBox.addActionListener(e -> handleSetLimitCheckbox());
        return checkBox;
    }

    /**
     * Creates the spinner to adjust the kill limit.
     *
     * @return A JSpinner for selecting the kill limit.
     */
    private JSpinner createLimitSpinner()
    {
        JSpinner spinner = new JSpinner(new SpinnerNumberModel(npcData.getKillLimit(), 0, Integer.MAX_VALUE, 1));
        spinner.setPreferredSize(new Dimension(70, 20));
        spinner.setMaximumSize(new Dimension(90, 20));
        spinner.setFont(OPTION_FONT);
        spinner.addChangeListener(e -> {
            if (updatingControls) {
                return;
            }
            int limit = (Integer) spinner.getValue();
            updateNpcData(data -> data.setKillLimit(limit));
        });
        return spinner;
    }

    /**
     * Creates the checkbox to enable notifications for reaching the kill limit.
     *
     * @return A JCheckBox to enable or disable notifications.
     */
    private JCheckBox createNotifyCheckbox()
    {
        JCheckBox checkBox = createCheckbox("Notify", npcData.isNotifyOnLimit());
        checkBox.addActionListener(e -> {
            boolean notify = checkBox.isSelected();
            updateNpcData(data -> data.setNotifyOnLimit(notify));
        });
        return checkBox;
    }

    private JCheckBox createCheckbox(String text, boolean selected) {
        JCheckBox checkBox = new JCheckBox(text, selected);
        checkBox.setForeground(Color.LIGHT_GRAY);
        checkBox.setBackground(new Color(60, 60, 60));
        checkBox.setFont(OPTION_FONT);
        return checkBox;
    }

    /**
     * Handles the action when the set limit checkbox is toggled.
     */
    private void handleSetLimitCheckbox()
    {
        boolean isChecked = setLimitCheckbox.isSelected();
        limitSpinner.setEnabled(isChecked);
        notifyCheckbox.setEnabled(isChecked);

        updatingControls = true;
        if (!isChecked) {
            limitSpinner.setValue(0); // Reset the spinner to 0
            notifyCheckbox.setSelected(false); // Uncheck notify
        } else if ((Integer) limitSpinner.getValue() == 0) {
            limitSpinner.setValue(10);
        }
        updatingControls = false;

        int limit = (Integer) limitSpinner.getValue();
        updateNpcData(data -> {
            data.setLimitSet(isChecked);
            data.setKillLimit(limit);
            if (!isChecked) {
                data.setNotifyOnLimit(false);
                data.resetKillCountForLimit();
            }
        });
    }

    private void updateNpcData(Consumer<NpcData> update) {
        if (sessionId == plugin.getSessionId()) {
            plugin.updateNpcData(npcData.getNpcName(), update);
        }
    }

    public void setNpcMenu(JPopupMenu menu) {
        setComponentPopupMenu(menu);
        optionsPanel.setInheritsPopupMenu(true);
        inheritContextMenu(this);
        inheritContextMenu(optionsPanel);
    }

    private void inheritContextMenu(Container parent) {
        for (Component child : parent.getComponents()) {
            if (child instanceof JComponent) {
                ((JComponent) child).setInheritsPopupMenu(true);
            }
            if (child instanceof Container) {
                inheritContextMenu((Container) child);
            }
        }
    }

    /**
     * Disables or enables option controls based on whether the NPC is ignored.
     */
    private void updateOptionStateBasedOnIgnored() {
        boolean isIgnored = npcData.isIgnored();
        setLimitCheckbox.setEnabled(!isIgnored);
        limitSpinner.setEnabled(!isIgnored && npcData.isLimitSet());
        notifyCheckbox.setEnabled(!isIgnored && npcData.isLimitSet());

        setBackground(isIgnored ? new Color(50, 50, 50) : new Color(60, 60, 60));
        toggleButton.setBackground(isIgnored ? new Color(50, 50, 50) : new Color(60, 60, 60));
        toggleButton.setForeground(isIgnored ? Color.GRAY : new Color(200, 150, 0));

    }

    /**
     * Sets the visibility of the dropdown options panel to the specified state.
     *
     * @param visible True to make the dropdown visible, false to hide it.
     */
    public void setDropdownVisible(boolean visible)
    {
        if (!SwingUtilities.isEventDispatchThread()) {
            SwingUtilities.invokeLater(() -> setDropdownVisible(visible));
            return;
        }
        if (visible == dropdownVisible) {
            return;
        }
        if (visible) {
            add(optionsPanel, BorderLayout.SOUTH);
        } else {
            remove(optionsPanel);
        }
        dropdownVisible = visible;
        toggleButton.setText(visible ? "▲" : "▼");
        revalidate();
        repaint();
        if (getParent() != null) {
            getParent().revalidate();
            getParent().repaint();
        }
    }
}

package com.monstermonitor.ui;

import com.monstermonitor.MonsterMonitorConfig;
import com.monstermonitor.data.NpcData;

import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import java.util.stream.Collectors;

/**
 * Represents the overlay used in Monster Monitor.
 * This overlay displays information about tracked NPCs, such as their names and the number of kills
 * towards a specified kill limit, along with a dynamic progress bar.
 */
@Singleton
public class MonsterMonitorOverlay extends Overlay {

    private static final Font TITLE_FONT = new Font("Arial", Font.BOLD, 14);
    private static final Font BAR_FONT = new Font("Arial", Font.BOLD, 12);
    private static final Color TITLE_COLOR = new Color(200, 150, 0);
    private static final Color BAR_BACKGROUND = new Color(60, 60, 60);
    private final AtomicReference<List<ProgressBar>> trackedNpcs = new AtomicReference<>(Collections.emptyList());
    private Font barFont = BAR_FONT;

    private final MonsterMonitorConfig config;

    /**
     * Constructs the MonsterMonitorOverlay and initializes the overlay's properties.
     *
     * @param config The MonsterMonitorConfig instance for user settings.
     */
    @Inject
    public MonsterMonitorOverlay(MonsterMonitorConfig config) {
        this.config = config;
        setPosition(OverlayPosition.TOP_CENTER);
        setLayer(OverlayLayer.ABOVE_SCENE);
        setResizable(true);
        setMovable(true);
        setPriority(55);

    }

    /**
     * Updates the list of tracked NPCs to be displayed on the overlay.
     * Filters out any NPCs that are currently ignored before updating.
     *
     * @param trackedNpcs The list of NPCs to be tracked and displayed.
     */
    public boolean updateOverlayData(List<NpcData> trackedNpcs) {
        List<ProgressBar> filteredNpcs = trackedNpcs.stream()
                .filter(npcData -> npcData.isLimitSet() && npcData.getKillLimit() > 0 && !npcData.isIgnored())
                .map(ProgressBar::new)
                .collect(Collectors.toCollection(ArrayList::new));
        Collections.reverse(filteredNpcs); // Reverse the order to display the most recent NPCs first
        this.trackedNpcs.set(filteredNpcs);
        return !filteredNpcs.isEmpty();
    }

    /**
     * Renders the overlay on the game screen, displaying tracked NPCs and their kill counts.
     *
     * @param graphics The Graphics2D object used for drawing the overlay.
     * @return The dimension of the rendered overlay.
     */
    @Override
    public Dimension render(Graphics2D graphics) {
        Dimension preferredSize = getPreferredSize();
        int overlayWidth = (preferredSize != null && preferredSize.width > 0) ? Math.max(30, preferredSize.width) : 160;

        List<ProgressBar> currentNpcs = trackedNpcs.get();
        if (currentNpcs.isEmpty()) {
            return null;
        }

        int yOffset = 0;

        // Calculate dynamic bar height based on the available space
        int totalBars = currentNpcs.size();
        int availableHeight = (preferredSize != null && preferredSize.height > 0) ? preferredSize.height : 0;
        int barHeight = Math.max(14, Math.min(availableHeight / (totalBars + 1), 30)); // Dynamically scale bar height

        // Render the title if enabled
        if (config.showTitle()) {
            graphics.setFont(TITLE_FONT);
            FontMetrics metrics = graphics.getFontMetrics();
            int titleX = (overlayWidth - metrics.stringWidth("Monster Monitor")) / 2;
            int titleY = yOffset + metrics.getAscent();

            // Draw the title
            graphics.setColor(Color.BLACK);
            graphics.drawString("Monster Monitor", titleX + 1, titleY + 1);
            graphics.setColor(TITLE_COLOR);
            graphics.drawString("Monster Monitor", titleX, titleY);

            yOffset += 20;
        } else {
            yOffset += 10;
        }

        // Render progress bars for each tracked NPC
        int fontSize = Math.max(11, barHeight - 2);
        if (barFont.getSize() != fontSize) {
            barFont = BAR_FONT.deriveFont((float) fontSize);
        }
        graphics.setFont(barFont);
        for (ProgressBar bar : currentNpcs) {
            drawProgressBar(graphics, bar, overlayWidth, barHeight, yOffset);
            yOffset += barHeight + 4; // Increment yOffset for the next bar
        }

        return new Dimension(overlayWidth, yOffset);
    }

    /**
     * Draws a progress bar for a specific NPC's kill progress toward the limit.
     *
     * @param graphics     The Graphics2D object used for drawing.
     * @param bar          The cached NPC progress and color.
     * @param overlayWidth The width of the overlay.
     * @param barHeight    The height of the progress bar.
     * @param yOffset      The vertical offset for drawing the bar.
     */
    private void drawProgressBar(Graphics2D graphics, ProgressBar bar, int overlayWidth, int barHeight, int yOffset) {
        int barWidth = overlayWidth - 10;
        int startX = (overlayWidth - barWidth) / 2;

        // Draw the progress bar background (gray)
        graphics.setColor(BAR_BACKGROUND);
        graphics.fillRect(startX, yOffset, barWidth, barHeight);

        // Draw the filled progress bar
        int filledWidth = (int) (bar.progress * barWidth);
        graphics.setColor(bar.color);
        graphics.fillRect(startX, yOffset, filledWidth, barHeight);

        // Draw a border around the progress bar
        graphics.setColor(Color.BLACK);
        graphics.drawRect(startX, yOffset, barWidth, barHeight);

        // Draw NPC name and progress text
        drawText(graphics, bar, startX, yOffset, barHeight, barWidth);
    }

    /**
     * Interpolates between three colors (customizable) based on a ratio.
     * The color transitions from the start color (0%) to the midpoint color (50%) to the end color (100%).
     *
     * @param ratio The progress ratio (0.0 to 1.0) used to determine the interpolated color.
     * @return The interpolated color corresponding to the given ratio.
     */
    private Color interpolateColor(double ratio) {
        Color startColor = config.progressBarStartColor();
        Color midColor = config.progressBarMidColor();
        Color endColor = config.progressBarEndColor();

        if (ratio <= 0.5) {
            // Interpolate between Start Color and Midpoint Color
            return interpolate(startColor, midColor, ratio * 2);
        } else {
            // Interpolate between Midpoint Color and End Color
            return interpolate(midColor, endColor, (ratio - 0.5) * 2);
        }
    }

    /**
     * Interpolates between two colors based on a given ratio.
     *
     * @param startColor The starting color.
     * @param endColor   The ending color.
     * @param ratio      The interpolation ratio (0.0 to 1.0).
     * @return The interpolated color.
     */
    private Color interpolate(Color startColor, Color endColor, double ratio) {
        int red = (int) (startColor.getRed() * (1 - ratio) + endColor.getRed() * ratio);
        int green = (int) (startColor.getGreen() * (1 - ratio) + endColor.getGreen() * ratio);
        int blue = (int) (startColor.getBlue() * (1 - ratio) + endColor.getBlue() * ratio);

        return new Color(red, green, blue);
    }

    /**
     * Draws the NPC name and kill progress text on top of the progress bar.
     * Dynamically adjusts font size, text alignment, and truncation based on available space.
     *
     * @param graphics         The Graphics2D object used for drawing.
     * @param bar              The cached NPC name and progress text.
     * @param startX           The starting X position for the text.
     * @param yOffset          The vertical offset for drawing the text.
     * @param barHeight        The height of the progress bar.
     * @param barWidth         The width of the progress bar.
     */
    private void drawText(Graphics2D graphics, ProgressBar bar, int startX, int yOffset, int barHeight, int barWidth) {
        FontMetrics metrics = graphics.getFontMetrics();
        int textY = yOffset + ((barHeight + metrics.getAscent() - metrics.getDescent()) / 2);

        // Calculate available width for the NPC name and progress text
        int availableTextWidth = barWidth - 10;

        // NPC Name (Left-aligned)
        String npcName = truncateText(bar.name, availableTextWidth / 2, metrics); // Allocate half width
        graphics.setColor(Color.BLACK);
        graphics.drawString(npcName, startX + 4, textY + 1); // Shadow
        graphics.setColor(Color.LIGHT_GRAY);
        graphics.drawString(npcName, startX + 3, textY);

        // Kill Progress Text (Right-aligned)
        String progressText = formatNumberDynamic(bar, availableTextWidth / 2, metrics);
        int textWidth = metrics.stringWidth(progressText);
        int textX = startX + barWidth - textWidth - 4; // Align to the right
        graphics.setColor(Color.BLACK);
        graphics.drawString(progressText, textX + 1, textY + 1); // Shadow
        graphics.setColor(Color.LIGHT_GRAY);
        graphics.drawString(progressText, textX, textY);
    }

    /**
     * Truncates a string to fit within a specified width, appending an ellipsis if necessary.
     *
     * @param text      The text to truncate.
     * @param maxWidth  The maximum width allowed for the text.
     * @param metrics   The FontMetrics used to measure the text width.
     */
    private String truncateText(String text, int maxWidth, FontMetrics metrics) {
        if (metrics.stringWidth(text) <= maxWidth) {
            return text;
        }

        // Truncate text and add ellipsis
        for (int i = text.length() - 1; i > 0; i--) {
            String truncated = text.substring(0, i) + "...";
            if (metrics.stringWidth(truncated) <= maxWidth) {
                return truncated;
            }
        }
        return metrics.stringWidth("...") <= maxWidth ? "..." : "";
    }

    /**
     * Formats the given number to a more readable string, such as 1k for 1000, without rounding up.
     *
     * @param number The number to format.
     * @return A formatted string representing the number.
     */
    private String formatNumber(int number) {
        if (number < 1_000) {
            return Integer.toString(number);
        }
        int divisor = number >= 1_000_000 ? 1_000_000 : 1_000;
        return number / divisor + "." + number / (divisor / 10) % 10 + (divisor == 1_000_000 ? "m" : "k");
    }

    /**
     * Dynamically formats the kill progress text (e.g., "125/500" or "125K/500K").
     * Expands or truncates the text based on available width.
     *
     * @param bar       The cached full and abbreviated progress text.
     * @param maxWidth  The maximum width allowed for the text.
     * @param metrics   The FontMetrics used to measure the text width.
     * @return A formatted string representing the kill progress, truncated if necessary.
     */
    private String formatNumberDynamic(ProgressBar bar, int maxWidth, FontMetrics metrics) {
        // Check if the full text fits
        if (metrics.stringWidth(bar.fullText) <= maxWidth) {
            return bar.fullText; // Return full text if it fits
        }

        // Use shortened format (e.g., 125K/500K)
        if (metrics.stringWidth(bar.shortText) <= maxWidth) {
            return bar.shortText;
        }

        return metrics.stringWidth("...") <= maxWidth ? "..." : "";
    }

    private class ProgressBar {
        private final String name;
        private final double progress;
        private final Color color;
        private final String fullText;
        private final String shortText;

        private ProgressBar(NpcData data) {
            name = data.getNpcName();
            int current = data.getKillCountForLimit();
            int limit = data.getKillLimit();
            progress = Math.max(0, Math.min(current / (double) limit, 1.0));
            color = interpolateColor(progress);
            fullText = current + "/" + limit;
            shortText = formatNumber(current) + "/" + formatNumber(limit);
        }
    }
}

package com.monstermonitor.ui;

import com.monstermonitor.MonsterMonitorPlugin;
import com.monstermonitor.data.NpcData;

import net.runelite.client.ui.PluginPanel;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.*;
import javax.swing.plaf.basic.BasicScrollBarUI;
import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.List;

/**
 * Represents the main panel of Monster Monitor.
 * This panel displays a list of NPCs that the player has been tracking, including their kill counts and
 * various options for managing the tracked data, including ignore/monitor status.
 * The panel also includes a title, total kill count display, and scrollable list of NPCs.
 */
@Singleton
public class MonsterMonitorPanel extends PluginPanel {
    private final MonsterMonitorPlugin plugin;
    private final MonsterMonitorSearchBar searchBar;
    private final JPanel npcListPanel;
    private final JPanel fillerBox; // The filler box at the bottom
    private final JLabel totalKillCountLabel;
    private final Map<String, Boolean> dropdownStates = new HashMap<>(); // Stores the state of dropdowns
    private String searchText = "";

    @Inject
    public MonsterMonitorPanel(MonsterMonitorPlugin plugin) {
        this.plugin = plugin;

        setLayout(new BorderLayout());
        Color backgroundColor = new Color(45, 45, 45);
        Color textColor = new Color(200, 200, 200);
        setBackground(backgroundColor);

        // Title Panel setup
        JPanel titlePanel = new JPanel(new BorderLayout());
        titlePanel.setBackground(backgroundColor);

        JLabel titleLabel = new JLabel("Monster Monitor", SwingConstants.CENTER);
        titleLabel.setFont(new Font("Arial", Font.BOLD, 14));
        titleLabel.setForeground(new Color(200, 150, 0));
        titleLabel.setHorizontalAlignment(SwingConstants.CENTER);

        ImageIcon icon = new ImageIcon(getClass().getResource("/net/runelite/client/plugins/MonsterMonitor/icon.png"));
        titleLabel.setIcon(icon);

        totalKillCountLabel = new JLabel("Total kills: 0");
        totalKillCountLabel.setFont(new Font("Arial", Font.BOLD, 12));
        totalKillCountLabel.setForeground(textColor);
        totalKillCountLabel.setHorizontalAlignment(SwingConstants.CENTER);

        titlePanel.add(titleLabel, BorderLayout.NORTH);
        titlePanel.add(totalKillCountLabel, BorderLayout.SOUTH);

        // Add the title panel at the top
        add(titlePanel, BorderLayout.NORTH);

        // Initialize the search bar and add it below the title panel
        searchBar = new MonsterMonitorSearchBar(searchText -> {
            this.searchText = searchText.toLowerCase();
            updatePanel();
        });
        add(searchBar, BorderLayout.CENTER);

        // NPC List Panels setup
        this.npcListPanel = new JPanel(new GridBagLayout());
        this.npcListPanel.setBackground(backgroundColor);
        this.npcListPanel.setBorder(BorderFactory.createEmptyBorder());
        add(npcListPanel, BorderLayout.SOUTH);

        JScrollPane scrollPane = getScrollPane();
        scrollPane.getVerticalScrollBar().setUI(new CustomScrollBarUI(new Color(200, 150, 0)));
        scrollPane.getVerticalScrollBar().setPreferredSize(new Dimension(2, 0));
        scrollPane.getVerticalScrollBar().setUnitIncrement(6);

        this.fillerBox = new JPanel();
        fillerBox.setBackground(backgroundColor); // Same background as the panel (invisible)
        fillerBox.setPreferredSize(new Dimension(0, 200)); // Initial height is large
    }

    /**
     * Captures the current dropdown state for all NPC panels before refreshing.
     */
    private void captureDropdownStates() {
        Component[] components = npcListPanel.getComponents();
        for (Component component : components) {
            if (component instanceof MonsterMonitorBox) {
                MonsterMonitorBox box = (MonsterMonitorBox) component;
                NpcData npcData = box.getNpcData();
                dropdownStates.put(npcData.getNpcName(), box.isDropdownVisible());
            }
        }
    }

    /**
     * Updates the panel by refreshing the list of tracked and ignored NPCs.
     */
    public void updatePanel() {
        if (!SwingUtilities.isEventDispatchThread()) {
            SwingUtilities.invokeLater(this::updatePanel);
            return;
        }
        captureDropdownStates();

        npcListPanel.removeAll();

        List<NpcData> trackedNpcs = new ArrayList<>();
        List<NpcData> ignoredNpcs = new ArrayList<>();
        Set<String> npcNames = new HashSet<>();
        long totalKills = 0;

        for (NpcData npcData : plugin.getTrackedNpcs()) {
            npcNames.add(npcData.getNpcName());
            totalKills += npcData.getTotalKillCount();
            // Apply search filter to both tracked and ignored NPCs
            if (npcData.getNpcName().toLowerCase().contains(searchText)) {
                (npcData.isIgnored() ? ignoredNpcs : trackedNpcs).add(npcData);
            }
        }
        dropdownStates.keySet().retainAll(npcNames);

        Collections.reverse(trackedNpcs);
        Collections.reverse(ignoredNpcs);

        GridBagConstraints gbc = new GridBagConstraints();
        gbc.gridx = 0;
        gbc.gridy = 0;
        gbc.weightx = 1.0;
        gbc.fill = GridBagConstraints.HORIZONTAL;
        gbc.insets = new Insets(5, 0, 5, 0);

        addNpcBoxes(trackedNpcs, gbc);

        if (!ignoredNpcs.isEmpty()) {
            JLabel ignoredLabel = new JLabel("Ignored NPCs", SwingConstants.CENTER);
            ignoredLabel.setForeground(new Color(180, 180, 180));
            ignoredLabel.setFont(new Font("Arial", Font.BOLD, 12));
            npcListPanel.add(ignoredLabel, gbc);
            gbc.gridy++;

            addNpcBoxes(ignoredNpcs, gbc);
        }

        adjustFillerBox(trackedNpcs.size() + ignoredNpcs.size());
        npcListPanel.add(fillerBox, gbc);

        totalKillCountLabel.setText("Total kills: " + totalKills);
        npcListPanel.revalidate();
        npcListPanel.repaint();

    }

    public void resetSession() {
        dropdownStates.clear();
        npcListPanel.removeAll();
        updatePanel();
    }

    private void addNpcBoxes(List<NpcData> npcs, GridBagConstraints gbc) {
        for (NpcData npcData : npcs) {
            MonsterMonitorBox npcPanel = new MonsterMonitorBox(plugin, npcData, dropdownStates.getOrDefault(npcData.getNpcName(), false));
            npcPanel.setNpcMenu(createContextMenu(npcData));
            npcListPanel.add(npcPanel, gbc);
            gbc.gridy++;
        }
    }

    private void adjustFillerBox(int npcCount) {
        int height = npcCount > 15 ? 0 : Math.max(100, 400 - npcCount * 15);
        fillerBox.setPreferredSize(new Dimension(0, height));
    }

    private JPopupMenu createContextMenu(NpcData npcData) {
        JPopupMenu contextMenu = new JPopupMenu();

        if (!npcData.isIgnored()) {
            contextMenu.add(createMenuItem("Ignore NPC", ev -> plugin.setNpcToIgnore(npcData.getNpcName())));
        }

        JMenu monitorMenu = new JMenu("Monitor");
        for (int preset : new int[]{1, 10, 100, 1000}) {
            monitorMenu.add(createMenuItem(Integer.toString(preset), ev -> plugin.setNpcToMonitor(npcData.getNpcName(), preset)));
        }

        // Add custom limit option
        monitorMenu.add(createMenuItem("Custom...", ev -> {
            int session = plugin.getSessionId();
            String input = JOptionPane.showInputDialog("Enter custom kill limit:");
            if (input == null || session != plugin.getSessionId()) {
                return;
            }
            try {
                int customLimit = parseNonNegative(input);
                plugin.setNpcToMonitor(npcData.getNpcName(), customLimit);
            } catch (NumberFormatException ignored) {
                JOptionPane.showMessageDialog(null, "Please enter a non-negative whole number.", "Invalid Input", JOptionPane.ERROR_MESSAGE);
            }
        }));
        contextMenu.add(monitorMenu);

        contextMenu.add(createMenuItem("Clear NPC Data", ev -> plugin.removeNpcFromLog(npcData.getNpcName())));
        contextMenu.add(createMenuItem("Reset Kill Limit", ev -> plugin.updateNpcData(npcData.getNpcName(), data -> {
            data.setKillLimit(0);
            data.setLimitSet(false);
            data.resetKillCountForLimit();
        })));

        // "Edit NPC Data" option to edit NPC Data from log
        contextMenu.add(createMenuItem("Edit NPC Data", ev -> showEditNpcDataDialog(npcData)));

        // Add Expand All and Collapse All
        contextMenu.addSeparator();
        contextMenu.add(createMenuItem("Collapse All", ev -> setDropdownsVisible(false)));
        contextMenu.add(createMenuItem("Expand All", ev -> setDropdownsVisible(true)));

        return contextMenu;
    }

    private JMenuItem createMenuItem(String text, ActionListener action) {
        JMenuItem item = new JMenuItem(text);
        int session = plugin.getSessionId();
        item.addActionListener(event -> {
            if (session == plugin.getSessionId()) {
                action.actionPerformed(event);
            }
        });
        return item;
    }

    private void showEditNpcDataDialog(NpcData npcData) {
        int session = plugin.getSessionId();
        JPanel panel = new JPanel(new GridLayout(4, 2));

        // Create input fields with current values prefilled
        JLabel npcNameField = new JLabel(String.valueOf(npcData.getNpcName()));
        JTextField totalKillsField = new JTextField(String.valueOf(npcData.getTotalKillCount()));
        JTextField killLimitField = new JTextField(String.valueOf(npcData.getKillLimit()));
        JTextField killsForLimitField = new JTextField(String.valueOf(npcData.getKillCountForLimit()));

        // Add labels and fields to the panel
        panel.add(new JLabel("NPC:"));
        panel.add(npcNameField);
        panel.add(new JLabel("Total Kills:"));
        panel.add(totalKillsField);
        panel.add(new JLabel("Kill Limit:"));
        panel.add(killLimitField);
        panel.add(new JLabel("Kills For Limit:"));
        panel.add(killsForLimitField);

        int result = JOptionPane.showConfirmDialog(null, panel, "Edit NPC Data", JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);

        if (result == JOptionPane.OK_OPTION && session == plugin.getSessionId()) {
            try {
                // Parse and set new values if valid
                int totalKills = parseNonNegative(totalKillsField.getText());
                int killLimit = parseNonNegative(killLimitField.getText());
                int killsForLimit = parseNonNegative(killsForLimitField.getText());

                plugin.updateNpcData(npcData.getNpcName(), data -> {
                    if (totalKills != npcData.getTotalKillCount()) {
                        data.setTotalKillCount(totalKills);
                    }
                    if (killLimit != npcData.getKillLimit()) {
                        data.setKillLimit(killLimit);
                        data.setLimitSet(killLimit > 0);
                    }
                    if (killsForLimit != npcData.getKillCountForLimit()) {
                        data.setKillCountForLimit(killsForLimit);
                    }
                });

            } catch (NumberFormatException e) {
                JOptionPane.showMessageDialog(null, "Please enter non-negative whole numbers.", "Invalid Input", JOptionPane.ERROR_MESSAGE);
            }
        }
    }

    private int parseNonNegative(String text) {
        int value = Integer.parseInt(text.trim());
        if (value < 0) {
            throw new NumberFormatException();
        }
        return value;
    }

    private void setDropdownsVisible(boolean visible) {
        for (Component component : npcListPanel.getComponents()) {
            if (component instanceof MonsterMonitorBox) {
                MonsterMonitorBox box = (MonsterMonitorBox) component;
                box.setDropdownVisible(visible);
            }
        }
        npcListPanel.revalidate();
        npcListPanel.repaint();
    }

    public static class CustomScrollBarUI extends BasicScrollBarUI {
        private final Color arrowColor;

        public CustomScrollBarUI(Color arrowColor) {
            this.arrowColor = arrowColor;
        }

        @Override
        protected void configureScrollBarColors() {
            this.thumbColor = arrowColor;
            this.trackColor = new Color(30, 30, 30);
        }

        @Override
        protected JButton createDecreaseButton(int orientation) {
            return createZeroButton();
        }

        @Override
        protected JButton createIncreaseButton(int orientation) {
            return createZeroButton();
        }

        private JButton createZeroButton() {
            JButton button = new JButton();
            button.setPreferredSize(new Dimension(0, 0));
            return button;
        }
    }
}

package com.monstermonitor.ui;

import com.monstermonitor.MonsterMonitorConfig;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WidgetNode;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayDeque;
import java.util.Queue;

/**
 * Handles displaying a modal popup when a player reaches the kill limit for an NPC.
 */
@Singleton
@Slf4j
public class MonsterMonitorPopup {
    private static final int SCRIPT_ID = 3343;
    private WidgetNode popupWidgetNode;
    private int popupParent;
    private final Queue<String> queuedPopups = new ArrayDeque<>();
    @Inject
    private Client client;
    @Inject
    private MonsterMonitorConfig config;
    private boolean active;

    public void startUpPopup() {
        active = true;
    }

    public void showPopup(String npcName) {
        if (active && config.showPopup()) {
            queuedPopups.add(npcName);
        }
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        if (!active || client.getGameState() != GameState.LOGGED_IN) {
            return;
        }
        if (!config.showPopup()) {
            shutdownPopup();
            active = true;
            return;
        }

        if (popupWidgetNode != null) {
            if (client.getComponentTable().get(popupParent) != popupWidgetNode) {
                popupWidgetNode = null;
            } else {
                Widget widget = client.getWidget(InterfaceID.NotificationDisplay.CONTAINER);
                if (widget != null && widget.getWidth() > 0) {
                    return;
                }
                closePopup();
            }
        }

        if (queuedPopups.isEmpty()) {
            return;
        }
        int componentId = getParentComponentId();
        if (client.getWidget(componentId) == null || client.getComponentTable().get(componentId) != null) {
            return;
        }

        try {
            popupWidgetNode = client.openInterface(componentId, InterfaceID.NOTIFICATION_DISPLAY, WidgetModalMode.MODAL_CLICKTHROUGH);
            if (popupWidgetNode != null) {
                popupParent = componentId;
                String npcName = queuedPopups.remove();
                client.runScript(SCRIPT_ID, "Monster Monitor", "You have reached the kill limit for " + npcName, -1);
            }
        } catch (RuntimeException e) {
            log.warn("Failed to display Monster Monitor popup", e);
            closePopup();
        }
    }

    /**
     * Determines the correct parent component ID based on the UI layout.
     */
    private int getParentComponentId() {
        if (client.isResized()) {
            return client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1
                    ? InterfaceID.ToplevelPreEoc.NOTIFICATIONS
                    : InterfaceID.ToplevelOsrsStretch.NOTIFICATIONS;
        }
        return InterfaceID.Toplevel.NOTIFICATIONS;
    }

    private void closePopup() {
        if (popupWidgetNode != null) {
            try {
                if (client.getComponentTable().get(popupParent) == popupWidgetNode) {
                    client.closeInterface(popupWidgetNode, true);
                }
            } catch (RuntimeException e) {
                log.warn("Failed to close Monster Monitor popup", e);
            }
            popupWidgetNode = null;
        }
    }

    /**
     * Properly clears all popups and resets the queue on shutdown.
     */
    public void shutdownPopup() {
        active = false;
        queuedPopups.clear();
        closePopup();
    }
}

package com.monstermonitor.ui;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import java.util.function.Consumer;

/**
 * A search bar component for filtering NPCs in Monster Monitor.
 * Displays a text field with a search icon, triggering real-time filtering as the text changes.
 */
public class MonsterMonitorSearchBar extends JPanel {
    public MonsterMonitorSearchBar(Consumer<String> listener) {
        setLayout(new BorderLayout());
        setBackground(new Color(45, 45, 45));
        setBorder(new EmptyBorder(5, 5, 5, 5));

        // Create a panel to hold the icon and search field together
        JPanel searchContainer = new JPanel(new BorderLayout());
        searchContainer.setBackground(new Color(30, 30, 30)); // Match search field background
        searchContainer.setBorder(BorderFactory.createEmptyBorder(2, 5, 2, 5)); // Padding

        // Search icon
        JLabel searchIcon = new JLabel("🔍"); //Magnifying glass
        searchIcon.setForeground(new Color(200, 200, 200));
        searchIcon.setBorder(new EmptyBorder(0, 5, 0, 5));

        JTextField searchField = new JTextField();
        searchField.setBackground(new Color(30, 30, 30)); // Dark background for visibility
        searchField.setForeground(Color.LIGHT_GRAY);
        searchField.setBorder(BorderFactory.createEmptyBorder(0, 5, 0, 5)); // Inner padding
        searchField.setCaretColor(Color.LIGHT_GRAY);

        searchField.getDocument().addDocumentListener(new DocumentListener() {
            @Override
            public void insertUpdate(DocumentEvent e) {
                listener.accept(searchField.getText());
            }

            @Override
            public void removeUpdate(DocumentEvent e) {
                listener.accept(searchField.getText());
            }

            @Override
            public void changedUpdate(DocumentEvent e) {
                listener.accept(searchField.getText());
            }
        });

        // Add icon and search field to the container panel
        searchContainer.add(searchIcon, BorderLayout.WEST);
        searchContainer.add(searchField, BorderLayout.CENTER);

        // Add the container panel to this search bar panel
        add(searchContainer, BorderLayout.CENTER);
    }
}

